static toRGBA(hsla) {
        const h = hsla.h / 360;
        const { s, l, a } = hsla;
        let r, g, b;
        if (s === 0) {
            r = g = b = l; // achromatic
        }
        else {
            const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
            const p = 2 * l - q;
            r = $Wn.i(p, q, h + 1 / 3);
            g = $Wn.i(p, q, h);
            b = $Wn.i(p, q, h - 1 / 3);
        }
        return new $Vn(Math.round(r * 255), Math.round(g * 255), Math.round(b * 255), a);
    }
